class BowlingGame:
    def __init__(self):
        self.rolls = []          # every roll, in order (used for scoring)
        self.frame = 0          # 0-indexed current frame number (0-9)
        self.frame_rolls = []   # rolls in the current frame (in progress)
        self.game_complete = False

    def roll(self, pins):
        if self.game_complete:
            raise Exception("Cannot roll after the game is over")
        if pins < 0 or pins > 10:
            raise Exception("Roll cannot score more than 10 points")

        if self.frame < 9:
            self._roll_regular_frame(pins)
        else:
            self._roll_tenth_frame(pins)

    def _roll_regular_frame(self, pins):
        if len(self.frame_rolls) == 0:
            # First roll of the frame.
            self.frame_rolls.append(pins)
            self.rolls.append(pins)
            if pins == 10:
                self._next_frame()
        else:
            # Second roll of the frame.
            if self.frame_rolls[0] + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points"
                )
            self.frame_rolls.append(pins)
            self.rolls.append(pins)
            self._next_frame()

    def _roll_tenth_frame(self, pins):
        r = self.frame_rolls
        if len(r) == 0:
            # First roll of the 10th frame.
            self.frame_rolls.append(pins)
            self.rolls.append(pins)
        elif len(r) == 1:
            # Second roll of the 10th frame.
            if r[0] != 10 and r[0] + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points"
                )
            self.frame_rolls.append(pins)
            self.rolls.append(pins)
            if r[0] != 10 and r[0] + pins < 10:
                # Open frame: no bonus roll.
                self.game_complete = True
        else:
            # Third (bonus) roll of the 10th frame.
            if r[0] == 10 and r[1] != 10 and r[1] + pins > 10:
                raise Exception(
                    "Bonus roll cannot score more than 10 points"
                )
            self.frame_rolls.append(pins)
            self.rolls.append(pins)
            self.game_complete = True

    def _next_frame(self):
        self.frame += 1
        self.frame_rolls = []

    def score(self):
        if not self.game_complete:
            raise Exception("Cannot score an incomplete game")
        return self._calculate_score()

    def _calculate_score(self):
        score = 0
        roll_index = 0
        for _ in range(10):
            if self.rolls[roll_index] == 10:
                # Strike: 10 plus the next two rolls.
                score += 10 + self.rolls[roll_index + 1] + self.rolls[roll_index + 2]
                roll_index += 1
            elif self.rolls[roll_index] + self.rolls[roll_index + 1] == 10:
                # Spare: 10 plus the next roll.
                score += 10 + self.rolls[roll_index + 2]
                roll_index += 2
            else:
                # Open frame: just the two rolls.
                score += self.rolls[roll_index] + self.rolls[roll_index + 1]
                roll_index += 2
        return score
